    /// Gmail（Simple Icons）
    static let gmail: NSImage = template(24, #"M24 5.457v13.909c0 .904-.732 1.636-1.636 1.636h-3.819V11.73L12 16.64l-6.545-4.91v9.273H1.636A1.636 1.636 0 0 1 0 19.366V5.457c0-2.023 2.309-3.178 3.927-1.964L5.455 4.64 12 9.548l6.545-4.91 1.528-1.145C21.69 2.28 24 3.434 24 5.457z"#)
    /// iCloud（Simple Icons）
    static let icloud: NSImage = template(24, #"M13.762 4.29a6.51 6.51 0 0 0-5.669 3.332 3.571 3.571 0 0 0-1.558-.36 3.571 3.571 0 0 0-3.516 3A4.918 4.918 0 0 0 0 14.796a4.918 4.918 0 0 0 4.92 4.914 4.93 4.93 0 0 0 .617-.045h14.42c2.305-.272 4.041-2.258 4.043-4.589v-.009a4.594 4.594 0 0 0-3.727-4.508 6.51 6.51 0 0 0-6.511-6.27z"#)

    private static func template(_ box: Int, _ path: String) -> NSImage {
        let svg = #"<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 \#(box) \#(box)" width="\#(box)" height="\#(box)"><path fill="black" d="\#(path)"/></svg>"#
        guard let vector = NSImage(data: Data(svg.utf8)) else {
            return NSImage(systemSymbolName: "app", accessibilityDescription: nil)!
        }
        // Rasterize once (64 px covers 16–32 pt at 2x): an SVG-backed NSImage re-renders its paths on every draw,
        // which made sidebar redraws stutter.
        let px = 64
        guard let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: px, pixelsHigh: px, bitsPerSample: 8,
                                         samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                                         colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0)
        else { vector.isTemplate = true; return vector }
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
        vector.draw(in: NSRect(x: 0, y: 0, width: px, height: px))
        NSGraphicsContext.restoreGraphicsState()
        rep.size = NSSize(width: box, height: box)
        let image = NSImage(size: NSSize(width: box, height: box))
        image.addRepresentation(rep)
        image.isTemplate = true
        return image
    }
}

extension Image {
    static var github: Image { Image(nsImage: BrandMark.github).renderingMode(.template) }
    static var wecom: Image { Image(nsImage: BrandMark.wecom).renderingMode(.template) }
}

/// A brand logo sized like an SF Symbol in a sidebar row.
struct BrandIcon: View {
    let image: NSImage
    var size: CGFloat = 15

    var body: some View {
        Image(nsImage: image).renderingMode(.template).resizable().scaledToFit().frame(width: size, height: size)
    }
}

